import json,urllib.request
d=json.loads(urllib.request.urlopen('http://127.0.0.1:17448/api/ai-profiles',timeout=8).read().decode())
out={'defaultAiProfileId':d.get('settings',{}).get('defaultAiProfileId'),'profiles':[]}
for p in d.get('aiProfiles',[]):
  out['profiles'].append({k:p.get(k) for k in ['id','name','provider','role','enabled','debugPort','chromeProfilePath','workerConnected','workerLikelyLoggedIn','workerLastSeenAt']})
print(json.dumps(out,ensure_ascii=True,separators=(',',':')))
